const $ = (s, el = document) => el.querySelector(s);
const $$ = (s, el = document) => [...el.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl = value => /^(https?:\/\/|\/(?!\/)|mailto:|tel:|data:(?:image\/(?:jpeg|png|webp)|application\/pdf);base64,)/i.test(value || '') ? esc(String(value).startsWith('/')?sitePath(value):value) : '#';
const arrow = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.7"/></svg>';
const northeast = '<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12" stroke="currentColor" stroke-width="1.7"/></svg>';
const flower = '<svg class="flower" viewBox="0 0 100 100" fill="none" aria-hidden="true"><path d="M50 4v92M4 50h92M17 17l66 66M17 83l66-66" stroke="currentColor" stroke-width="21"/><circle cx="50" cy="50" r="14" fill="var(--cream)"/></svg>';
const config = window.SFW_CONFIG || {mode:'demo'};
const basePath = (config.basePath||'').replace(/\/$/,'');
function sitePath(path){return !basePath||path===basePath||path.startsWith(basePath+'/')?path:basePath+path;}
function localPath(path){return !basePath?path:path===basePath?'/':path.startsWith(basePath+'/')?path.slice(basePath.length):null;}
function mount(markup){return !basePath?markup:markup.replace(/\b(href|src)="(\/[^\"]*)"/g,(_,attribute,path)=>`${attribute}="${sitePath(path)}"`);}
const live = config.mode === 'production' && config.supabaseUrl && config.supabasePublishableKey;
let original, data, route = (localPath(location.pathname)||'/').replace(/\/$/, '') || '/', projectFilter = 'All', projectSearch = '', partnerSearch = '', adminKind = 'projects', adminSession = false, adminSearch = '', adminStatus = 'all';
let session;
try {session = JSON.parse(sessionStorage.getItem('sfw-session') || 'null');} catch {session = null;}
const publicKinds = ['projects','partners','reports','testimonials','team'];
const notify = message => {const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),4000);};
const img = (src, alt, extra='') => `<img src="${safeUrl(src)}" alt="${esc(alt)}" ${extra.includes('loading=')?'':'loading="lazy"'} ${extra}>`;
const button = (label, href, cls='button') => `<a class="${cls}" href="${safeUrl(href)}">${label}${arrow}</a>`;
const wordmark = `<a class="wordmark" href="/" aria-label="Stand For Women home"><span>STAND FOR</span><strong>WOMEN<span class="logo-dot">✳</span></strong></a>`;
const published = kind => (data[kind] || []).filter(x=>!x.status || x.status==='published');

async function api(path, options={}) {
  const response = await fetch(config.supabaseUrl+path, {...options, headers:{apikey:config.supabasePublishableKey,Authorization:`Bearer ${session?.access_token || config.supabasePublishableKey}`,'Content-Type':'application/json',...options.headers}});
  const body = await response.json().catch(()=>null);
  if(!response.ok)throw new Error(body?.msg || body?.message || body?.error_description || 'The request could not be completed.');
  return body;
}
async function refreshSession(){
  if(session?.refresh_token && session.expires_at && session.expires_at*1000<Date.now()+60000){
    const result=await api('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:session.refresh_token})});
    session={...result,expires_at:Math.floor(Date.now()/1000)+result.expires_in};sessionStorage.setItem('sfw-session',JSON.stringify(session));
  }
}
async function loadContent(all=false){
  if(!live)return;
  await refreshSession();
  const rows=await api('/rest/v1/content_entries?select=*'+(all?'':'&status=eq.published')+'&order=created_at.asc');
  for(const kind of publicKinds){
    const entries=rows.filter(x=>x.kind===kind).map(x=>({...x.data,id:x.id,status:x.status,slug:x.slug,title:x.title || x.data?.title}));
    data[kind]=entries;
  }
  if(all&&session&&config.workerUrl){
    await Promise.all(publicKinds.flatMap(kind=>(data[kind]||[]).filter(item=>item.status==='draft'&&item.media_key).map(async item=>{
      const response=await fetch(config.workerUrl+'/api/media/preview',{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json'},body:JSON.stringify({key:item.media_key})});
      if(response.ok){const preview=await response.json();if(kind==='reports')item.url=preview.url;else item.image=preview.url;}
    })));
  }
}
function persist(){if(!live)localStorage.setItem('sfw-content-v1',JSON.stringify(data));}
function navLink(label,path){return `<a href="${path}" ${route===path?'aria-current="page"':''}>${label}</a>`;}
function header(){return `<div class="announcement"><span>Economic opportunity. Lasting independence. A stronger future.</span><a href="/about">Our story ${northeast}</a></div><header class="site-header"><div class="container header-inner">${wordmark}<nav aria-label="Main navigation">${navLink('Our story','/about')}${navLink('What we do','/programs')}${navLink('Our impact','/impact')}${navLink('Projects','/projects')}<a href="/get-involved" class="nav-involve">Get involved</a></nav><a class="button small" href="/get-involved#give">Stand with her ${northeast}</a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false"><span></span><span></span></button></div></header>`;}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-top"><div><span class="eyebrow">THERE'S A PLACE FOR YOU HERE</span><h2>Change starts with <em>us.</em></h2></div>${button('Find your way to give back','/get-involved','button light')}</div><div class="footer-grid"><div>${wordmark}<p>Championing women’s economic empowerment,<br>gender equality, and the power of sisterhood.</p><div class="socials"><a href="https://www.instagram.com/istandforwomen/" target="_blank" rel="noopener noreferrer" aria-label="Stand For Women on Instagram">Instagram ${northeast}</a><a href="mailto:stand@standforwomen.org">Email us ${northeast}</a></div></div><div><span class="footer-label">EXPLORE</span><a href="/about">Our story</a><a href="/programs">What we do</a><a href="/projects">Our projects</a><a href="/partners">Our partners</a></div><div><span class="footer-label">TAKE PART</span><a href="/get-involved#volunteer">Volunteer with us</a><a href="/get-involved#partner">Become a partner</a><a href="/get-involved#give">Make a contribution</a><a href="/impact">Read our impact reports</a></div><div><span class="footer-label">SAY HELLO</span><a href="mailto:stand@standforwomen.org">stand@standforwomen.org</a><a href="tel:+96178788652">+961 78 788652</a><p>Fattal Building, Jisr El Wati<br>Sin El Fil, Lebanon</p></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Stand For Women. Growing stronger, together.</span><span>Rooted in Lebanon. Connected by purpose.</span><a href="/admin">Staff access ${northeast}</a></div></div></footer>`;}
function pageIntro(kicker,title,description,extra=''){return `<section class="page-intro container"><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p>${extra}</section>`;}
function projectCard(p){return `<article class="project-card"><a href="/projects/${esc(p.slug)}" class="project-image">${img(p.image,p.title)}<span class="image-arrow">${northeast}</span><span class="image-tag">${esc(p.category)}</span></a><div class="project-card-body"><span class="eyebrow">A STAND FOR WOMEN COLLABORATION</span><h3><a href="/projects/${esc(p.slug)}">${esc(p.title)}</a></h3><p>${esc(p.description)}</p></div></article>`;}
function programRows(){return `<div class="program-rows">${[
  ['01','Stronger businesses.','Support for women-led SMEs','Practical support, new skills and meaningful connections to help women-owned businesses sustain and grow.','enterprise'],
  ['02','Confident leaders.','Leadership & coaching','Creating space for women to develop their skills, find their voice and take their next step with confidence.','leadership'],
  ['03','Brighter possibilities.','Youth education & work','Connecting young women with role models, shared experiences and opportunities to imagine their futures.','youth']
].map(([n,title,label,desc,key])=>`<a class="program-row" href="/programs#${key}"><span class="program-number">${n}</span><div><span class="eyebrow">${label}</span><h3>${title}</h3></div><p>${desc}</p><span class="round-arrow">${northeast}</span></a>`).join('')}</div>`;}
function home(){
 const selected=['al-fanar','fnf-lebanon','beirut-footsteps'].map(name=>published('projects').find(p=>p.slug.includes(name))).filter(Boolean);
 const reports=published('reports');
 return `<section class="hero container"><div class="hero-copy"><span class="eyebrow"><span class="tiny-flower">✳</span> ROOTED IN LEBANON. RISING TOGETHER.</span><h1>When she rises,<br>we <em>all rise.</em></h1><p>Every woman deserves the opportunity to shape her own future. We stand beside her—with the support, skills and sisterhood to make it possible.</p><div class="hero-actions">${button('Discover our work','/programs')}<a href="/get-involved" class="text-link">Be part of the change ${northeast}</a></div><div class="hero-note"><div class="avatar-stack">${published('team').map(t=>img(t.image,t.name)).join('')}</div><span>Women supporting women.<br><strong>Since 2017. Always together.</strong></span></div></div><div class="hero-visual"><div class="hero-photo">${img(data.photos.hero,'Women from the Stand For Women community together outdoors','fetchpriority="high" loading="eager"')}<span class="photo-caption"><i></i> REAL PEOPLE. SHARED POSSIBILITY.</span></div><div class="hero-stamp"><svg viewBox="0 0 120 120" aria-hidden="true"><defs><path id="seal-path" d="M60,60 m-43,0 a43,43 0 1,1 86,0 a43,43 0 1,1 -86,0"/></defs><text><textPath href="#seal-path" textLength="265">STRONGER TOGETHER • STRONGER TOGETHER • </textPath></text></svg>${flower}</div><div class="hero-caption"><span class="handwritten">A little support.<br>A world of possibility.</span><svg viewBox="0 0 80 45" aria-hidden="true"><path d="M4 6c22 35 48 30 65 8m-20 2 22-5-3 21" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></div></div></section>
 <div class="belief-strip"><div class="container"><span>Economic empowerment</span><b>✳</b><span>Equal opportunity</span><b>✳</b><span>Lasting independence</span><b>✳</b><span>The power of sisterhood</span></div></div>
 <section class="section container mission"><div><span class="eyebrow">THE BELIEF THAT BRINGS US TOGETHER</span><h2>Invest in a woman.<br>See what <em>changes.</em></h2></div><div class="mission-copy"><p class="lead">A livelihood becomes independence.<br>Confidence becomes opportunity.<br>One woman’s progress becomes a community’s strength.</p><p>Founded in Lebanon in 2017, Stand For Women advocates for women’s economic empowerment and gender equality across the Middle East. We believe meaningful change grows when we stand together.</p><a href="/about" class="text-link">Get to know us ${arrow}</a></div></section>
 <section class="program-section"><div class="container"><div class="section-heading"><div><span class="eyebrow">OPPORTUNITY TAKES MANY FORMS</span><h2>Our purpose.<br><em>Put into practice.</em></h2></div><p>Three areas of focus.<br>One belief in women’s potential.</p></div>${programRows()}</div></section>
 <section class="section container"><div class="section-heading"><div><span class="eyebrow">COLLABORATION IN ACTION</span><h2>Small steps.<br><em>Meaningful change.</em></h2></div>${button('Explore our projects','/projects','text-link')}</div><div class="project-grid">${selected.map(projectCard).join('')}</div></section>
 <section class="impact-feature"><div class="impact-photo">${img(data.photos.community,'Stand For Women volunteers and community members')}</div><div class="impact-copy"><span class="eyebrow">THE MARION FUND</span><h2>From heartbreak,<br><em>a helping hand.</em></h2><p>Created in memory of Marion Hochar Ibrahimchah after the Beirut port explosion, the Marion Fund supports women-led businesses as they rebuild their livelihoods.</p><div class="impact-numbers"><div><strong>170<span>+</span></strong><span>SMEs supported</span></div><div><strong>295</strong><span>SMEs assessed</span></div></div><p class="data-note">Historical figures reported on the Marion Fund page, August 2022.</p>${button('The story behind the fund','/programs#marion','button light')}</div></section>
 ${communityQuote('home')}
 <section class="report-section"><div class="container report-inner"><div><span class="eyebrow">BEHIND EVERY NUMBER, A STORY</span><h2>See the difference<br>we’re making.</h2><a href="/impact" class="text-link">Explore our impact ${arrow}</a></div><div class="report-list">${reports.slice().reverse().map(r=>`<a href="${safeUrl(r.url)}" target="_blank" rel="noopener" class="report-row"><span class="report-icon">↗</span><div><span class="eyebrow">IMPACT REPORT</span><strong>${esc(r.period)}</strong></div><span class="report-format">PDF · ${esc(r.size)}</span>${northeast}</a>`).join('')}</div></div></section>
 <section class="section container partner-teaser"><span class="eyebrow">PROGRESS IS A COLLECTIVE EFFORT</span><h2>Good company.<br><em>Greater possibilities.</em></h2><div class="partner-strip">${published('partners').filter(p=>p.image).filter(p=>/abaad|fanar|berytech|google|oxfam|un women/i.test(p.name)).slice(0,6).map(p=>img(p.image,p.name)).join('')}</div><a href="/partners" class="text-link">Meet the people standing with us ${arrow}</a></section>`;
}
function about(){return `${pageIntro('OUR STORY','A shared purpose.<br><em>A stronger tomorrow.</em>','We are Stand For Women. A Lebanon-based non-governmental organization championing women’s economic empowerment, gender equality and sisterhood since 2017.')}<section class="container about-photo">${img(data.photos.team,'Members of the Stand For Women team')}<div class="photo-label">Independent women.<br>Interconnected futures.</div></section><section class="section container split"><div><span class="eyebrow">WHAT WE STAND FOR</span><h2>Opportunity is<br><em>for every woman.</em></h2></div><div><p class="lead">We envision an environment free of discrimination and violence, where women have equal opportunities to lead, work and thrive.</p><p>Our work connects women-led businesses with practical support, develops leadership and confidence, and introduces young people to inspiring women across industries.</p><p>From supporting vulnerable businesses through crises to creating connections between women, we put economic independence at the heart of lasting change.</p></div></section><section class="values-section"><div class="container"><span class="eyebrow">OUR VALUES</span><div class="values-grid"><div><span>01</span><h3>Empowerment.</h3><p>The tools, resources and confidence to shape your own future.</p></div><div><span>02</span><h3>Equality.</h3><p>Opportunity and participation, grounded in merit and free of discrimination.</p></div><div><span>03</span><h3>Sisterhood.</h3><p>Women standing alongside one another, sharing knowledge and opening doors.</p></div></div></div></section><section class="section container"><div class="section-heading"><div><span class="eyebrow">THE WOMEN BEHIND THE WORK</span><h2>Purpose meets<br><em>people.</em></h2></div><p>A shared commitment to<br>making possibility real.</p></div><div class="team-grid">${published('team').map(t=>`<article>${img(t.image,t.name)}<span class="eyebrow">${esc(t.role)}</span><h3>${esc(t.name)}</h3><p>${esc(t.bio)}</p></article>`).join('')}</div></section><section class="container governance"><span class="eyebrow">GOVERNANCE & TRANSPARENCY</span><p>Stand For Women is a registered association in Lebanon: Ministry of Interior No. 2359 and Ministry of Finance No. 3400443.</p>${button('Read our impact reports','/impact','text-link')}</section>`;}
function programs(){return `${pageIntro('WHAT WE DO','Potential is everywhere.<br><em>Opportunity should be, too.</em>','We work alongside women at different stages of their journeys—from sustaining a business to building leadership skills and imagining what comes next.')}<div class="container">${programRows()}</div>${[
 ['enterprise','01 / SUPPORT FOR WOMEN-LED BUSINESSES','A livelihood.<br>A foundation for <em>independence.</em>','Women-owned businesses support families, create jobs and strengthen communities. We connect them with practical help and partners who can support their next step.',['Business continuity and crisis support','Digital marketing and business development workshops','Connections, collaboration and market opportunities'],data.photos.enterprise],
 ['leadership','02 / LEADERSHIP & COACHING','Her voice.<br>Her next <em>chapter.</em>','Through coaching, workshops and partner-led programs, we help women develop their capabilities and find new confidence in their work.',['Individual coaching and collective workshops','Leadership and entrepreneurship development','Skills for navigating change'],data.photos.workshop],
 ['youth','03 / YOUTH EDUCATION & WORK','Real role models.<br><em>New possibilities.</em>','We bring women leaders and young people together to share journeys across medicine, business, design, sport and other fields—offering inspiration and perspective for their futures.',['Inspiring conversations with women leaders','Shared experiences across industries','A focus on opportunity, diversity and equality'],data.photos.youth]
].map(([id,k,title,desc,points,image],i)=>`<section id="${id}" class="section container program-detail ${i%2?'reverse':''}"><div class="program-detail-image">${img(image,k)}</div><div><span class="eyebrow">${k}</span><h2>${title}</h2><p>${desc}</p><ul class="check-list">${points.map(p=>`<li>${p}</li>`).join('')}</ul>${button('Explore related collaborations','/projects','text-link')}</div></section>`).join('')}<section id="marion" class="marion-section"><div class="container split"><div><span class="eyebrow">THE MARION FUND</span><h2>Keeping her memory.<br><em>Rebuilding futures.</em></h2></div><div><p class="lead">The Marion Fund honors Marion Hochar Ibrahimchah, who lost her life in the Beirut port explosion on August 4, 2020.</p><p>Created to support women-owned businesses affected by the blast, the fund prioritizes vulnerable women, businesses that sustain jobs, and enterprises preserving Beirut’s heritage and culture.</p><p>Its support has included reconstruction, in-kind assistance, cash support and opportunities to develop business skills.</p>${button('Explore our impact reports','/impact')}</div></div></section>`;}
function projects(){return `${pageIntro('OUR PROJECTS','Different partnerships.<br><em>One shared purpose.</em>','Discover the collaborations that bring support, skills and new possibilities to women in Lebanon.')}<section class="container projects-section"><div class="filter-bar"><div class="filter-tabs" role="group" aria-label="Filter projects">${['All','Enterprise','Leadership','Community'].map(c=>`<button data-filter="${c}" class="filter-tab ${projectFilter===c?'active':''}" aria-pressed="${projectFilter===c}">${c}${c==='All'?` <span>${published('projects').length}</span>`:''}</button>`).join('')}</div><label class="search-box"><span class="sr-only">Search projects</span><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6" fill="none" stroke="currentColor" stroke-width="1.5"/><path d="m15 15 5 5" stroke="currentColor" stroke-width="1.5"/></svg><input type="search" id="project-search" placeholder="Find a collaboration" value="${esc(projectSearch)}"></label></div><div id="project-results" aria-live="polite">${projectResults()}</div></section>`;}
function projectResults(){const list=published('projects').filter(p=>(projectFilter==='All'||p.category===projectFilter)&&`${p.title} ${p.description}`.toLowerCase().includes(projectSearch.toLowerCase()));return `<p class="result-count">${list.length} collaboration${list.length===1?'':'s'} · Many ways to make a difference.</p><div class="project-grid">${list.map(projectCard).join('')}</div>${!list.length?'<div class="empty-state"><h3>No matching collaborations.</h3><p>Try another search or explore all projects.</p><button class="button" data-reset-search>Show all projects</button></div>':''}`;}
function projectDetail(slug){const p=published('projects').find(p=>p.slug===slug);if(!p)return notFound();return `<div class="container breadcrumb"><a href="/projects">${arrow} All projects</a><span>${esc(p.category)}</span></div>${pageIntro('COLLABORATION IN ACTION',esc(p.title),'A Stand For Women collaboration.')}<div class="container project-cover">${img(p.image,p.title,'loading="eager"')}</div><section class="section container project-story"><aside><span class="eyebrow">THE COLLABORATION</span><h3>${esc(p.title)}</h3><span class="project-category">${esc(p.category)}</span><a href="/get-involved#partner" class="text-link">Partner with us ${northeast}</a></aside><div><span class="eyebrow">A SHARED COMMITMENT TO WOMEN</span>${(p.body?.length?p.body:[p.description]).map(t=>`<p>${esc(t)}</p>`).join('')}</div></section>${p.gallery?.length>1?`<section class="container gallery-section"><div class="section-heading"><h2>Moments from<br><em>the journey.</em></h2><span>Click a photo to explore</span></div><div class="gallery-grid">${p.gallery.map((src,i)=>`<button data-gallery="${i}" data-project="${esc(p.id)}" aria-label="Enlarge photo ${i+1} from ${esc(p.title)}">${img(src,`${p.title} — photo ${i+1}`)}<span>${northeast}</span></button>`).join('')}</div></section>`:''}<section class="section container"><div class="section-heading"><div><span class="eyebrow">KEEP EXPLORING</span><h2>More ways we<br><em>stand together.</em></h2></div><a href="/projects" class="text-link">All collaborations ${arrow}</a></div><div class="project-grid">${published('projects').filter(x=>x.id!==p.id).slice(0,3).map(projectCard).join('')}</div></section>`;}
function partners(){return `${pageIntro('OUR PARTNERS','Good intentions.<br><em>Greater together.</em>','Organizations, businesses, associations and universities sharing their expertise and resources to support women’s economic empowerment.')}<section class="container partners-section"><div class="filter-bar"><span class="result-count">${published('partners').length} partners. A shared commitment.</span><label class="search-box"><span class="sr-only">Search partners</span><input id="partner-search" type="search" placeholder="Find a partner" value="${esc(partnerSearch)}"></label></div><div class="partners-grid" id="partner-results">${partnerResults()}</div><div class="partner-invitation"><span class="eyebrow">LET'S BUILD SOMETHING MEANINGFUL</span><h2>Your expertise.<br><em>Our shared impact.</em></h2><p>There are many ways to stand with women. Let’s find where your organization can make a difference.</p>${button('Start a conversation','/get-involved#partner')}</div></section>`;}
function partnerResults(){const list=published('partners').filter(p=>p.name.toLowerCase().includes(partnerSearch.toLowerCase()));return list.length?list.map(p=>`<a class="partner-card" href="${safeUrl(p.website||'/contact')}" ${p.website?'target="_blank" rel="noopener noreferrer"':''}>${p.image?img(p.image,p.name):`<strong>${esc(p.name)}</strong>`}<span>${esc(p.name)} ${northeast}</span></a>`).join(''):'<p class="empty-state">No partners match your search.</p>';}
function impact(){return `${pageIntro('OUR IMPACT','The work matters.<br><em>So does accountability.</em>','Explore our published reports and the stories behind our work supporting women’s economic empowerment in Lebanon.')}<section class="container report-covers">${published('reports').slice().reverse().map((r,i)=>`<a class="report-cover cover-${i}" href="${safeUrl(r.url)}" target="_blank" rel="noopener"><span class="eyebrow">STAND FOR WOMEN</span><div>${flower}<h2>Our impact.<br><em>${esc(r.period)}</em></h2></div><span class="report-cover-bottom">Read the report · PDF · ${esc(r.size)} ${northeast}</span></a>`).join('')}</section><section class="section container split"><div><span class="eyebrow">THE MARION FUND · HISTORICAL SNAPSHOT</span><h2>Rebuilding businesses.<br><em>Restoring possibilities.</em></h2></div><div><p class="lead">Following the Beirut port explosion, the Marion Fund provided support to women-led businesses through reconstruction, in-kind assistance and cash support.</p><div class="impact-numbers"><div><strong>170+</strong><span>SMEs supported</span></div><div><strong>295</strong><span>SMEs assessed</span></div></div><p class="data-note">Figures reported on the original Marion Fund page, August 2022. Refer to the reports above for their respective reporting periods.</p></div></section><section class="values-section"><div class="container split"><div><span class="eyebrow">QUESTIONS ABOUT OUR WORK?</span><h2>Let’s talk<br><em>about impact.</em></h2></div><div><p>We welcome conversations about our programs, partnerships and published reports.</p>${button('Get in touch','/contact')}</div></div></section>`;}
function getInvolved(){return `${pageIntro('STAND WITH US','Your time. Your voice.<br><em>Your kind of change.</em>','Volunteer, share your expertise, build a partnership or contribute to our work. There is more than one way to stand for women.')}<div class="container involved-hero">${img(data.photos.merch,'Stand For Women volunteers supporting the organization together')}</div><section id="volunteer" class="section container split"><div><span class="eyebrow">01 / GIVE YOUR TIME</span><h2>A little of your time.<br><em>A lot of possibility.</em></h2></div><div><p class="lead">Join our community as a volunteer or intern.</p><p>From fundraising and marketing to project management, your skills can help turn our shared purpose into practical support for women.</p>${button('Tell us about yourself','/contact?interest=volunteer')}</div></section><section id="partner" class="values-section"><div class="container split"><div><span class="eyebrow">02 / SHARE YOUR EXPERTISE</span><h2>Bring what you do.<br><em>Build what matters.</em></h2></div><div><p class="lead">Meaningful partnerships start with a conversation.</p><p>We collaborate with businesses, organizations and institutions to create opportunities for women through skills, resources and connections.</p>${button('Let’s explore a partnership','/contact?interest=partnership')}</div></div></section><section id="give" class="section container split"><div><span class="eyebrow">03 / SUPPORT THE WORK</span><h2>Stand beside her.<br><em>Help her move forward.</em></h2></div><div><p class="lead">Your contribution can support the work of Stand For Women.</p><p>Contact our team for current donation options and the right way to contribute from Lebanon or abroad.</p>${button('Ask about making a contribution','mailto:stand@standforwomen.org?subject=Supporting%20Stand%20For%20Women')}<p class="data-note">Donation arrangements are handled directly by the Stand For Women team.</p></div></section>${communityQuote('volunteer')}`;}
function contact(){const interest=new URLSearchParams(location.search).get('interest');return `${pageIntro('LET’S START A CONVERSATION','A hello can be<br><em>the beginning.</em>','Have a question, an idea or a little time to give? We would love to hear from you.')}<section class="container contact-layout"><div class="contact-card"><span class="eyebrow">FIND US IN LEBANON</span><h3>Connected by purpose.<br>Always open to conversation.</h3><a href="mailto:stand@standforwomen.org">stand@standforwomen.org ${northeast}</a><a href="tel:+96178788652">+961 78 788652 ${northeast}</a><p>${esc(data.contact.address)}</p><p>Monday–Friday · 8:00 am–5:00 pm</p>${flower}</div><form id="contact-form" class="contact-form"><div class="form-row"><label>First name<input name="firstName" autocomplete="given-name" required maxlength="100" placeholder="Your first name"></label><label>Last name<input name="lastName" autocomplete="family-name" required maxlength="100" placeholder="Your last name"></label></div><label>Email address<input name="email" type="email" autocomplete="email" required maxlength="254" placeholder="you@example.com"></label><label>I’d like to talk about<select name="interest"><option value="general">A general inquiry</option><option value="volunteer" ${interest==='volunteer'?'selected':''}>Volunteering or an internship</option><option value="partnership" ${interest==='partnership'?'selected':''}>A partnership</option><option value="business">Support for my business</option><option value="donation">Making a contribution</option></select></label><label>Your message<textarea name="message" rows="5" required maxlength="5000" placeholder="Tell us a little about yourself and what you have in mind."></textarea></label><label class="honey" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><p class="form-note">Your details will be used to respond to your inquiry.</p><button type="submit" class="button">${config.workerUrl?'Send your message':'Continue in your email app'}${arrow}</button><p class="form-feedback" role="status"></p></form></section>`;}
function notFound(){return `<section class="section container empty-state"><span class="eyebrow">A DIFFERENT PATH</span><h1>This page isn’t here.</h1><p>There’s still plenty to discover.</p>${button('Back to our story','/')}</section>`;}

function communityQuote(source){
 const quotes=published('testimonials');
 const quote=source==='volunteer'?(quotes.find(t=>t.name==='Christa Maria Daher')||quotes.find(t=>t.source?.includes('volunteering'))):(quotes.find(t=>!t.source?.includes('volunteering')));
 if(!quote)return '';
 return `<section class="section container voices"><span class="eyebrow">${source==='home'?'IN HER OWN WORDS':'THE EXPERIENCE OF GIVING BACK'}</span><div class="quote-mark">&#8220;</div><blockquote>${esc(quote.text)}</blockquote><div class="quote-author"><span class="author-line"></span><strong>${esc(quote.name)}</strong><span>${source==='home'?'From our community':esc(quote.role||'Volunteer')}</span></div>${flower}</section>`;
}
function adminLogin(){return `<main class="admin-login"><a href="/" class="admin-back">${arrow} Back to website</a><section class="login-story">${wordmark}<span class="eyebrow">THE STAND FOR WOMEN STUDIO</span><h1>Your stories.<br><em>Ready to grow.</em></h1><p>A simple space to share your work,<br>celebrate your community and keep your website moving.</p>${img(data.photos.hero,'Stand For Women community')}</section><section class="login-form"><span class="eyebrow">WELCOME BACK</span><h2>A little behind<br><em>the scenes.</em></h2>${live?`<form id="login-form"><label>Email address<input name="email" type="email" required autocomplete="username"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button type="submit" class="button">Sign in securely ${arrow}</button><p class="form-feedback" role="alert"></p></form>`:`<p>Explore how easy it can be to manage projects, partners and reports using the site’s existing templates.</p><button class="button" id="enter-demo">Explore the dashboard ${arrow}</button><p class="demo-note">LOCAL DEMONSTRATION<br>Changes are saved only in this browser. No live website or account is affected.</p>`}</section></main>`;}
const adminLabels={projects:'Projects',partners:'Partners',reports:'Impact reports',testimonials:'Testimonials',team:'Our team'};
function adminShell(){return `<div class="admin-layout"><aside class="admin-sidebar">${wordmark}<div class="studio-label">CONTENT STUDIO</div><nav aria-label="Dashboard navigation"><button class="admin-nav ${adminKind==='overview'?'active':''}" data-admin-kind="overview"><span>&#9707;</span> Overview</button>${Object.entries(adminLabels).map(([key,name])=>`<button class="admin-nav ${adminKind===key?'active':''}" data-admin-kind="${key}"><span>${({projects:'\u25a4',partners:'\u25c8',reports:'\u25a5',testimonials:'\u275e',team:'\u2667'})[key]}</span> ${name}<small>${(data[key]||[]).length}</small></button>`).join('')}</nav><div class="admin-sidebar-bottom"><a href="/" target="_blank">View website ${northeast}</a>${!live?'<button id="reset-demo">Reset demo &#8634;</button>':''}<button id="sign-out">${live?'Sign out':'Leave dashboard'} ${arrow}</button></div></aside><main class="admin-main"><header class="admin-topbar"><span>Stand For Women / ${adminKind==='overview'?'Overview':adminLabels[adminKind]}</span><div><span class="mode-pill">${live?'Connected securely':'Local demo &#183; this browser only'}</span><span class="user-avatar">SW</span></div></header><div class="admin-content">${adminKind==='overview'?adminOverview():adminCollection()}</div></main></div>`;}
function adminCollection(){return `<div class="admin-page-heading"><div><span class="eyebrow">MAKE YOUR WORK VISIBLE</span><h1>${adminLabels[adminKind]}</h1><p>Your content, beautifully presented in its own template.</p></div><button class="button" data-create>+ Add ${adminKind==='team'?'team member':adminKind==='testimonials'?'testimonial':adminKind==='partners'?'partner':adminKind==='reports'?'report':'project'}</button></div><div class="admin-collection-tools"><label class="search-box"><span class="sr-only">Search dashboard entries</span><input type="search" id="admin-search" placeholder="Find an entry" value="${esc(adminSearch)}"></label><label class="status-filter"><span>Visibility</span><select id="admin-status" aria-label="Filter entries by visibility"><option value="all" ${adminStatus==='all'?'selected':''}>All entries</option><option value="published" ${adminStatus==='published'?'selected':''}>Published</option><option value="draft" ${adminStatus==='draft'?'selected':''}>Drafts</option></select></label></div><div id="admin-results">${adminTable()}</div>`;}
function adminTable(){
 const rows=(data[adminKind]||[]).map((item,index)=>({item,index})).filter(({item})=>(adminStatus==='all'||(item.status||'published')===adminStatus)&&`${item.title||''} ${item.name||''} ${item.role||''} ${item.category||''}`.toLowerCase().includes(adminSearch.toLowerCase()));
 return `<p class="admin-results-count" role="status">${rows.length} ${rows.length===1?'entry':'entries'} &#183; ${(data[adminKind]||[]).length} total</p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>${adminKind==='partners'||adminKind==='team'?'Name':'Title'}</th><th>Status</th><th>Template</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${rows.map(({item,index})=>`<tr><td><div class="table-title">${item.image?img(item.image,''):('<span class="table-icon">'+(adminKind==='reports'?'&#8599;':'&#10035;')+'</span>')}<div><strong>${esc(item.title||item.name||item.period||'Untitled')}</strong><span>${esc(item.category||item.role||item.website||item.period||'')}</span></div></div></td><td><span class="status ${item.status==='draft'?'draft':'published'}">${item.status==='draft'?'Draft':'Published'}</span></td><td>${({projects:'Project story',partners:'Partner profile',reports:'PDF report',testimonials:'Community quote',team:'Team profile'})[adminKind]}</td><td><button class="edit-button" data-edit="${index}">Edit ${northeast}</button></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty-state"><h3>No entries to show.</h3><p>Try another search, change the visibility filter or add a new entry.</p></div>':''}</div>`;
}
function bindAdminTable(){$$('[data-edit]').forEach(b=>b.onclick=()=>editor(Number(b.dataset.edit)));}
function resetDemo(){
 const dialog=document.createElement('dialog');dialog.className='confirm-dialog';dialog.innerHTML=`<h2>A fresh start?</h2><p>This removes the demo changes saved in this browser and restores the original content. The live website is unaffected.</p><div><button class="secondary-button" data-cancel>Keep my changes</button><button class="button" data-confirm>Restore demo</button></div>`;document.body.append(dialog);dialog.showModal();$('[data-cancel]',dialog).onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();$('[data-confirm]',dialog).onclick=()=>{const previous=data;data=structuredClone(original);try{persist();adminSearch='';adminStatus='all';adminKind='overview';dialog.close();render();notify('The demo has been restored. Ready for a fresh walkthrough.');}catch{data=previous;notify('Unable to reset browser storage.');}};
}
function adminOverview(){return `<div class="admin-page-heading"><div><span class="eyebrow">A LITTLE WORK. A LOT OF POSSIBILITY.</span><h1>Welcome to your studio.</h1><p>Everything you need to keep your community in the picture.</p></div><a class="button" href="/" target="_blank">View website ${northeast}</a></div><div class="admin-stats">${[['projects','Project stories'],['partners','Partners'],['reports','Impact reports'],['testimonials','Community voices']].map(([key,label])=>`<button data-admin-kind="${key}"><span>${label}</span><strong>${(data[key]||[]).length}</strong><small>${published(key).length} published ${arrow}</small></button>`).join('')}</div><div class="admin-welcome"><div><span class="eyebrow">YOUR NEXT STORY IS WAITING</span><h2>Good work deserves<br><em>to be shared.</em></h2><p>Add a project, choose a photo and tell the story.<br>Your website takes care of the layout.</p><button class="button" data-start-project>Create a project ${arrow}</button></div>${img(data.photos.community,'The Stand For Women community')}</div><div class="admin-tips"><div><span>01</span><h3>Choose a template</h3><p>Each content type has its own clear, consistent design.</p></div><div><span>02</span><h3>Make it yours</h3><p>Add your words, images and links. Save a draft as you go.</p></div><div><span>03</span><h3>Share when ready</h3><p>Preview your entry and publish it for your community.</p></div></div>`;}
function editor(index){const item=index===null?{}:data[adminKind][index];const textField=(name,label,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${['title','name'].includes(name)?'required':''} maxlength="${name==='description'?1500:500}"></label>`;let fields='';
 if(adminKind==='projects')fields=textField('title','Project title',item.title)+textField('slug','URL slug',item.slug)+`<label>Area of focus<select name="category">${['Enterprise','Leadership','Community'].map(c=>`<option ${item.category===c?'selected':''}>${c}</option>`).join('')}</select></label>`+textField('description','Short introduction',item.description)+`<label>The story<textarea name="body" rows="8">${esc((item.body||[]).join('\n\n'))}</textarea><small>Separate paragraphs with a blank line.</small></label>`;
 if(adminKind==='partners')fields=textField('name','Partner name',item.name)+textField('website','Website link',item.website,'url');
 if(adminKind==='team')fields=textField('name','Full name',item.name)+textField('role','Role',item.role)+`<label>Biography<textarea name="bio" rows="6">${esc(item.bio)}</textarea></label>`;
 if(adminKind==='testimonials')fields=textField('name','Author’s name',item.name)+textField('role','Role / context',item.role)+`<label>Quote<textarea name="text" rows="7" required>${esc(item.text)}</textarea></label>`;
 if(adminKind==='reports')fields=textField('title','Report title',item.title)+textField('period','Reporting period',item.period)+textField('url','PDF URL',item.url)+textField('size','File size label',item.size);
 const media=adminKind!=='testimonials'?`<div class="editor-media"><label>${adminKind==='reports'?'PDF document':'Cover image'}<input type="file" id="media-upload" accept="${adminKind==='reports'?'.pdf':'image/jpeg,image/png,image/webp'}"></label>${adminKind!=='reports'?`<input type="hidden" name="image" value="${esc(item.image||'')}"><div id="image-preview">${item.image?img(item.image,'Selected image'):''}</div><button type="button" class="secondary-button" id="choose-existing-image">Choose from the media library</button><br>`:''}<small>${live?'Files are uploaded securely to private storage until publication.':'Demo uploads are stored locally in this browser. Maximum 2 MB.'}</small></div>`:'';
 const dialog=document.createElement('dialog');dialog.className='editor-dialog';dialog.innerHTML=`<form id="entry-form"><div class="editor-header"><div><span class="eyebrow">${index===null?'A NEW CHAPTER':'MAKE IT YOURS'}</span><h2>${index===null?'Add':'Edit'} ${adminLabels[adminKind].toLowerCase()}</h2></div><button type="button" class="close-dialog" aria-label="Close editor">×</button></div><div class="editor-fields">${fields}${media}<label>Visibility<select name="status"><option value="draft" ${item.status==='draft'||index===null?'selected':''}>Draft · Only visible in the dashboard</option><option value="published" ${item.status!=='draft'&&index!==null?'selected':''}>Published · Visible on the website</option></select></label><p class="form-feedback" role="alert"></p></div><div class="editor-footer">${index!==null?'<button type="button" class="delete-button" id="delete-entry">Delete entry</button>':'<span>Built around your content.</span>'}<div><button type="button" class="secondary-button" id="preview-entry">Preview</button><button type="submit" class="button">Save entry ${arrow}</button></div></div></form>`;document.body.append(dialog);dialog.showModal();dialog.addEventListener('close',()=>dialog.remove());$('.close-dialog',dialog).onclick=()=>dialog.close();
 let uploaded=null;
 $('#choose-existing-image',dialog)?.addEventListener('click',()=>{
   const choices=[...new Set([...Object.values(data.photos),...data.projects.flatMap(p=>[p.image,...p.gallery||[]]),...data.partners.map(p=>p.image),...data.team.map(p=>p.image)].filter(Boolean))];
   const library=document.createElement('dialog');library.className='media-library';library.innerHTML=`<div class="editor-header"><div><span class="eyebrow">YOUR SHARED MEDIA</span><h2>Find the right image.</h2></div><button class="close-dialog" aria-label="Close media library">×</button></div><div class="media-choices">${choices.map((src,i)=>`<button type="button" data-choice="${i}" aria-label="Choose image ${i+1}">${img(src,`Media library image ${i+1}`)}</button>`).join('')}</div>`;
   document.body.append(library);library.showModal();$('.close-dialog',library).onclick=()=>library.close();library.onclose=()=>library.remove();$$('[data-choice]',library).forEach(b=>b.onclick=()=>{const src=choices[Number(b.dataset.choice)];$('[name="image"]',dialog).value=src;$('#image-preview',dialog).innerHTML=img(src,'Selected image');uploaded=null;library.close();});
 });
 $('#media-upload',dialog)?.addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;const feedback=$('.form-feedback',dialog);try{
   if(live){
     if(!config.workerUrl)throw new Error('Secure media endpoint is not configured.');
     await refreshSession();const response=await fetch(config.workerUrl+'/api/media',{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,'Content-Type':file.type,'X-File-Name':encodeURIComponent(file.name)},body:file});
     const result=await response.json();if(!response.ok)throw new Error(result.error||'Upload failed.');uploaded=result;
     feedback.textContent='Upload received. It stays private until this entry is published.';
   }else{if(file.size>2*1024*1024)throw new Error('Choose a file smaller than 2 MB for the local demo.');const reader=new FileReader();uploaded=await new Promise((resolve,reject)=>{reader.onload=()=>resolve({url:reader.result});reader.onerror=reject;reader.readAsDataURL(file);});}
   const input=$(`[name="${adminKind==='reports'?'url':'image'}"]`,dialog);input.value=uploaded.url;
   const preview=$('#image-preview',dialog);if(preview){preview.replaceChildren();const image=document.createElement('img');image.src=uploaded.url;image.alt='Selected image';preview.append(image);}
 }catch(error){feedback.textContent=error.message;}});
 const values=()=>{const raw=Object.fromEntries(new FormData($('#entry-form',dialog)));delete raw.file;let value={...item,...raw};if(adminKind==='projects'){value.body=raw.body.split(/\n\s*\n/).filter(Boolean);value.slug=(raw.slug||raw.title).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');value.gallery=value.gallery||[];}if(uploaded?.key)value.media_key=uploaded.key;return value;};
 $('#preview-entry',dialog).onclick=()=>{const v=values();const preview=document.createElement('dialog');preview.className='entry-preview';preview.innerHTML=`<button class="close-dialog" aria-label="Close preview">×</button><span class="eyebrow">ENTRY PREVIEW · NOT PUBLISHED</span>${v.image?img(v.image,v.title||v.name):''}<h2>${esc(v.title||v.name)}</h2>${(v.body||[v.description||v.bio||v.text||v.period||'']).map(t=>`<p>${esc(t)}</p>`).join('')}`;document.body.append(preview);preview.showModal();$('.close-dialog',preview).onclick=()=>preview.close();preview.onclose=()=>preview.remove();};
 $('#entry-form',dialog).onsubmit=async event=>{event.preventDefault();const submit=$('[type="submit"]',dialog);submit.disabled=true;try{const v=values();await saveEntry(v,index);dialog.close();render();notify(v.status==='published'?'Published. Your website is up to date.':'Draft saved. Your story is safe.');}catch(error){$('.form-feedback',dialog).textContent=error.message;}finally{submit.disabled=false;}};
 $('#delete-entry',dialog)?.addEventListener('click',()=>{const confirmation=document.createElement('dialog');confirmation.className='confirm-dialog';confirmation.innerHTML=`<h2>Delete this entry?</h2><p>This removes it from the dashboard and website.</p><div><button class="secondary-button" data-cancel>Keep entry</button><button class="button" data-confirm>Delete entry</button></div><p role="alert"></p>`;document.body.append(confirmation);confirmation.showModal();$('[data-cancel]',confirmation).onclick=()=>confirmation.close();confirmation.onclose=()=>confirmation.remove();$('[data-confirm]',confirmation).onclick=async()=>{try{if(live)await api('/rest/v1/content_entries?id=eq.'+encodeURIComponent(item.id),{method:'DELETE'});data[adminKind].splice(index,1);persist();confirmation.close();dialog.close();render();notify('Entry deleted.');}catch(error){$('[role="alert"]',confirmation).textContent=error.message;}};});
}
async function saveEntry(value,index){
 if(adminKind==='projects'){
   if(!value.slug)throw new Error('Please add a project title or page address.');
   if(data.projects.some((p,i)=>i!==index&&p.slug===value.slug))throw new Error('Another project uses that page address. Please choose a different one.');
   if(value.status==='published'&&!value.image)throw new Error('Choose a cover image before publishing your project.');
 }
 if(live){
   if(value.media_key && config.workerUrl){const response=await fetch(config.workerUrl+'/api/media/visibility',{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json'},body:JSON.stringify({key:value.media_key,status:value.status})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Unable to set file visibility.');if(adminKind==='reports')value.url=result.url;else value.image=result.url;}
   const payload={kind:adminKind,title:value.title||value.name||'',slug:value.slug||null,status:value.status,data:value};
   const rows=await api('/rest/v1/content_entries'+(index===null?'':'?id=eq.'+encodeURIComponent(value.id)),{method:index===null?'POST':'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(payload)});
   value.id=rows[0].id;
 }else value.id=value.id||crypto.randomUUID();
 const previous=structuredClone(data[adminKind]);
 if(index===null)data[adminKind].push(value);else data[adminKind][index]=value;
 try{persist();}catch(error){data[adminKind]=previous;throw new Error('Browser storage is full. Use a smaller image or remove a demo upload.');}
}
function bind(){
 $('.menu-toggle')?.addEventListener('click',e=>{const expanded=e.currentTarget.getAttribute('aria-expanded')==='true';e.currentTarget.setAttribute('aria-expanded',!expanded);e.currentTarget.setAttribute('aria-label',expanded?'Open navigation':'Close navigation');$('.site-header').classList.toggle('menu-open',!expanded);});
 $$('[data-filter]').forEach(b=>b.onclick=()=>{projectFilter=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});$('#project-results').innerHTML=mount(projectResults());bindReset();});
 $('#project-search')?.addEventListener('input',e=>{projectSearch=e.target.value;$('#project-results').innerHTML=mount(projectResults());bindReset();});bindReset();
 $('#partner-search')?.addEventListener('input',e=>{partnerSearch=e.target.value;$('#partner-results').innerHTML=mount(partnerResults());});
 $$('[data-gallery]').forEach(b=>b.onclick=()=>openGallery(b.dataset.project,Number(b.dataset.gallery)));
 $('#enter-demo')?.addEventListener('click',()=>{adminSession=true;adminKind='overview';render();});
 $('#login-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const submit=$('[type="submit"]',form);submit.disabled=true;try{const raw=Object.fromEntries(new FormData(form));const result=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify(raw)});session={...result,expires_at:Math.floor(Date.now()/1000)+result.expires_in};const admins=await api('/rest/v1/admins?select=user_id&user_id=eq.'+encodeURIComponent(result.user.id));if(!admins.length)throw new Error('This account does not have content administrator access.');sessionStorage.setItem('sfw-session',JSON.stringify(session));await loadContent(true);adminSession=true;adminKind='overview';render();}catch(error){session=null;sessionStorage.removeItem('sfw-session');$('.form-feedback',form).textContent=error.message;}finally{submit.disabled=false;}});
 $('#sign-out')?.addEventListener('click',async()=>{if(live){try{await api('/auth/v1/logout',{method:'POST'});}catch{}session=null;sessionStorage.removeItem('sfw-session');await loadContent();}adminSession=false;render();});
 $$('[data-admin-kind]').forEach(b=>b.onclick=()=>{adminKind=b.dataset.adminKind;adminSearch='';adminStatus='all';render();});
 $('[data-create]')?.addEventListener('click',()=>editor(null));
 $('[data-start-project]')?.addEventListener('click',()=>{adminKind='projects';render();editor(null);});
 bindAdminTable();
 $('#admin-search')?.addEventListener('input',e=>{adminSearch=e.target.value;$('#admin-results').innerHTML=adminTable();bindAdminTable();});
 $('#admin-status')?.addEventListener('change',e=>{adminStatus=e.target.value;$('#admin-results').innerHTML=adminTable();bindAdminTable();});
 $('#reset-demo')?.addEventListener('click',resetDemo);
 $('#contact-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;const values=Object.fromEntries(new FormData(form));if(values.website)return;const feedback=$('.form-feedback',form);const submit=$('[type="submit"]',form);try{submit.disabled=true;if(config.workerUrl){const res=await fetch(config.workerUrl+'/api/contact',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(values)});const body=await res.json();if(!res.ok)throw new Error(body.error||'Your message could not be sent. Please email us directly.');feedback.textContent='Thank you. Your message has been sent to our team.';form.reset();}else{const subject=`Stand For Women — ${values.interest}`;const body=`Name: ${values.firstName} ${values.lastName}\nEmail: ${values.email}\n\n${values.message}`;location.href=`mailto:stand@standforwomen.org?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;feedback.textContent='Your email app will open with your message. Send it there to contact the team.';}}catch(error){feedback.textContent=error.message;}finally{submit.disabled=false;}});
}
function bindReset(){$('[data-reset-search]')?.addEventListener('click',()=>{projectFilter='All';projectSearch='';render();});}
function openGallery(id,index){const p=data.projects.find(p=>p.id===id);let active=index;const dialog=document.createElement('dialog');dialog.className='gallery-dialog';dialog.innerHTML=`<button class="close-dialog" aria-label="Close gallery">×</button><button class="gallery-prev" aria-label="Previous photo">←</button><figure><img alt=""><figcaption></figcaption></figure><button class="gallery-next" aria-label="Next photo">→</button>`;document.body.append(dialog);const update=()=>{$('img',dialog).src=p.gallery[active];$('img',dialog).alt=`${p.title} — photo ${active+1}`;$('figcaption',dialog).textContent=`${p.title} · ${active+1} / ${p.gallery.length}`;};const next=direction=>{active=(active+direction+p.gallery.length)%p.gallery.length;update();};$('.gallery-prev',dialog).onclick=()=>next(-1);$('.gallery-next',dialog).onclick=()=>next(1);$('.close-dialog',dialog).onclick=()=>dialog.close();dialog.onkeydown=e=>{if(e.key==='ArrowLeft')next(-1);if(e.key==='ArrowRight')next(1);};dialog.onclose=()=>dialog.remove();update();dialog.showModal();}
function render(){
 const admin=route==='/admin';document.body.classList.toggle('is-admin',admin);
 if(admin){$('#app').innerHTML=mount(adminSession?adminShell():adminLogin());document.title='Content Studio — Stand For Women';bind();return;}
 let page,title;
 switch(route){case '/':page=home();title='When she rises, we all rise.';break;case '/about':page=about();title='Our story';break;case '/programs':page=programs();title='What we do';break;case '/projects':page=projects();title='Our projects';break;case '/partners':page=partners();title='Our partners';break;case '/impact':page=impact();title='Our impact';break;case '/get-involved':page=getInvolved();title='Get involved';break;case '/contact':page=contact();title='Get in touch';break;default:page=route.startsWith('/projects/')?projectDetail(route.split('/')[2]):notFound();title=route.startsWith('/projects/')?data.projects.find(p=>p.slug===route.split('/')[2])?.title||'Project':'Page not found';}
 $('#app').innerHTML=mount(header()+`<main id="main">${page}</main>`+footer());document.title=`${title} — Stand For Women`;bind();
}
document.addEventListener('click',async event=>{const a=event.target.closest('a');if(!a || event.defaultPrevented || event.button!==0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || a.target || a.hasAttribute('download'))return;const url=new URL(a.href,location.origin);if(url.origin!==location.origin || localPath(url.pathname)===null || /\.(pdf|webp|png|jpg)$/i.test(url.pathname))return;event.preventDefault();history.pushState({},'',url.pathname+url.search+url.hash);route=(localPath(url.pathname)||'/').replace(/\/$/,'')||'/';if(live&&route==='/admin'&&adminSession){try{await loadContent(true);}catch(error){notify(error.message);}}render();if(url.hash){requestAnimationFrame(()=>document.getElementById(url.hash.slice(1))?.scrollIntoView({behavior:'smooth'}));}else window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('popstate',()=>{route=(localPath(location.pathname)||'/').replace(/\/$/,'')||'/';render();if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView());});
async function init(){try{const res=await fetch(sitePath('/content.json'));if(!res.ok)throw new Error('Content could not be loaded.');original=await res.json();data=structuredClone(original);if(!live){try{const saved=JSON.parse(localStorage.getItem('sfw-content-v1'));if(saved?.projects&&saved?.partners)data={...original,...saved};}catch{}}else{await loadContent();if(session){try{const admins=await api('/rest/v1/admins?select=user_id');if(admins.length){adminSession=true;if(route==='/admin')await loadContent(true);}}catch{session=null;sessionStorage.removeItem('sfw-session');}}}render();if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView());}catch(error){$('#app').innerHTML=`<main class="empty-state container"><h1>We’ll be right with you.</h1><p>Our content could not be loaded. Please try again shortly.</p><a class="button" href="mailto:stand@standforwomen.org">Contact the team</a></main>`;console.error(error);}}
init();
